// Service worker for the Networking with Go, Made Easy website.
// Provides offline reading: the app shell is precached (list generated by
// website/tools/buildreader into sw-precache.js), and every visited page is
// cached on the fly with a stale-while-revalidate strategy so the reader
// keeps working with no connection.

importScripts('sw-precache.js');

var CACHE = 'nwg-v4';
var CORE = (typeof PRECACHE_URLS !== 'undefined') ? PRECACHE_URLS : [];

self.addEventListener('install', function (e) {
  e.waitUntil(
    caches.open(CACHE).then(function (cache) {
      return cache.addAll(CORE);
    }).then(function () {
      return self.skipWaiting();
    }).catch(function () {
      // If a precache entry fails (e.g. missing on first build), still let
      // the worker activate and rely on runtime caching.
    })
  );
});

self.addEventListener('activate', function (e) {
  e.waitUntil(
    caches.keys().then(function (keys) {
      return Promise.all(keys.map(function (key) {
        if (key !== CACHE) return caches.delete(key);
      }));
    }).then(function () {
      return self.clients.claim();
    })
  );
});

self.addEventListener('fetch', function (e) {
  if (e.request.method !== 'GET') return;

  var url = new URL(e.request.url);
  if (url.origin !== self.location.origin) return;

  // Navigations are network-first: a deploy must be visible on the next page
  // load, not one reload later. The cache is the offline fallback.
  if (e.request.mode === 'navigate') {
    e.respondWith(
      fetch(e.request).then(function (res) {
        if (res && res.status === 200 && res.type === 'basic') {
          var clone = res.clone();
          caches.open(CACHE).then(function (cache) { cache.put(e.request, clone); });
        }
        return res;
      }).catch(function () {
        return caches.match(e.request).then(function (cached) {
          return cached || caches.match('read/index.html');
        });
      })
    );
    return;
  }

  // Everything else is cache-first with a background refresh. reader.css and
  // reader.js carry a content hash in the query string (see buildreader), so
  // a changed asset always misses the cache instead of serving an old build.
  e.respondWith(
    caches.match(e.request).then(function (cached) {
      var fetchPromise = fetch(e.request).then(function (res) {
        if (res && res.status === 200 && res.type === 'basic') {
          var clone = res.clone();
          caches.open(CACHE).then(function (cache) { cache.put(e.request, clone); });
        }
        return res;
      }).catch(function () {
        if (cached) return cached;
        return caches.match('read/index.html');
      });
      return cached || fetchPromise;
    })
  );
});
